-- PostgreSQL schema for SONAE
CREATE TABLE users (id SERIAL PRIMARY KEY, username VARCHAR(100) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(30) NOT NULL DEFAULT 'city');
CREATE TABLE sites (id SERIAL PRIMARY KEY, name VARCHAR(200) NOT NULL, location VARCHAR(200) NOT NULL, site_type VARCHAR(100) NOT NULL, population INTEGER NOT NULL DEFAULT 0, mode VARCHAR(30) NOT NULL DEFAULT 'normal', rate INTEGER NOT NULL DEFAULT 20 CHECK (rate IN (15,20,40)), contact_name VARCHAR(150) NOT NULL DEFAULT '', contact_phone VARCHAR(100) NOT NULL DEFAULT '', pin VARCHAR(20) UNIQUE NOT NULL, blocked BOOLEAN NOT NULL DEFAULT FALSE, generator_on BOOLEAN NOT NULL DEFAULT FALSE, pump_on BOOLEAN NOT NULL DEFAULT FALSE, sewer_ok BOOLEAN NOT NULL DEFAULT TRUE, map_x INTEGER NOT NULL DEFAULT 50, map_y INTEGER NOT NULL DEFAULT 50);
CREATE TABLE bladders (id SERIAL PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, label VARCHAR(50) NOT NULL, capacity INTEGER NOT NULL CHECK (capacity > 0), fill INTEGER NOT NULL DEFAULT 0 CHECK (fill >= 0), status VARCHAR(30) NOT NULL DEFAULT 'standby' CHECK (status IN ('standby','active','full')), disposal_method VARCHAR(100), disposal_note TEXT, disposed_at TIMESTAMP, UNIQUE(site_id,label));
CREATE INDEX ix_bladders_site_id ON bladders(site_id);
CREATE TABLE transfers (id SERIAL PRIMARY KEY, from_site_id INTEGER NOT NULL REFERENCES sites(id), to_site_id INTEGER NOT NULL REFERENCES sites(id), size INTEGER NOT NULL, count INTEGER NOT NULL DEFAULT 1 CHECK(count > 0), status VARCHAR(30) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','intransit','completed')), note TEXT NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(from_site_id <> to_site_id));
CREATE TABLE vacuum_vendors (id SERIAL PRIMARY KEY, company VARCHAR(200) NOT NULL, phone VARCHAR(100) NOT NULL, area VARCHAR(200) NOT NULL, response_time VARCHAR(100) NOT NULL, contracted BOOLEAN NOT NULL DEFAULT FALSE, available BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE manual_sections (id SERIAL PRIMARY KEY, slug VARCHAR(40) UNIQUE NOT NULL, icon VARCHAR(20) NOT NULL DEFAULT '', title VARCHAR(200) NOT NULL, subtitle VARCHAR(200) NOT NULL DEFAULT '', diagram_note VARCHAR(250) NOT NULL DEFAULT '');
CREATE TABLE manual_steps (id SERIAL PRIMARY KEY, section_id INTEGER NOT NULL REFERENCES manual_sections(id) ON DELETE CASCADE, step_no INTEGER NOT NULL, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, UNIQUE(section_id,step_no));
